// Isolated fictional workspace: no production account, providers or application writes.
import {build} from 'esbuild';
import {createServer} from 'node:http';
import {mkdtemp,readFile,rm} from 'node:fs/promises';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {fileURLToPath} from 'node:url';
const root=fileURLToPath(new URL('../../',import.meta.url));
const dir=await mkdtemp(join(tmpdir(),'si-example-ui-'));
await build({stdin:{contents:`import React,{useEffect,useRef,useState} from 'react';import {createRoot} from 'react-dom/client';import {CareerProvider,useCareer,emptyData} from './src/career-data';import {CareerTools} from './src/career';import './src/styles.css';
const saved={...emptyData(),profile:{...emptyData().profile,cv:'PRIVATE FICTIONAL EXISTING CV — must remain unchanged.',name:'Fictional Existing Applicant'}};
const key='si.career.guest.v2';localStorage.setItem(key,JSON.stringify({data:saved,revision:0,dirty:false}));
let calls=0,writes=0;const set=Storage.prototype.setItem;
Storage.prototype.setItem=function(k,v){writes++;return set.call(this,k,v);};
window.fetch=async(url)=>{if(String(url)==='/api/auth/get-session')return Response.json({user:null});calls++;return Response.json({error:'No external request allowed in this fixture'},{status:400});};
function View(){const c=useCareer(),[mode,go]=useState('studio'),[baseline,setBaseline]=useState(null),[tick,refresh]=useState(0);useEffect(()=>{const timer=setInterval(()=>refresh(t=>t+1),250);return()=>clearInterval(timer);},[]);return <main style={{padding:20,maxWidth:1000,margin:'auto'}}><h1>Fictional first-use QA</h1><p>No production data or external providers.</p><p aria-label="QA viewport">Viewport {document.documentElement.clientWidth}px; page width {document.documentElement.scrollWidth}px</p><button onClick={()=>setBaseline({data:JSON.stringify(c.data),writes,calls})} disabled={!c.ready}>Set QA baseline</button><p role="status" aria-label="QA result">{baseline?'Workspace unchanged: '+String(baseline.data===JSON.stringify(c.data))+'; additional storage writes: '+(writes-baseline.writes)+'; external attempts: '+(calls-baseline.calls):'Waiting for QA baseline'}</p><p aria-label="QA saved CV">{c.data.profile.cv}</p><p>Current destination: {mode}</p><button onClick={()=>go('studio')}>Return to example</button>{mode==='studio'?<CareerTools mode="studio" go={go}/>:<p>Navigation reached {mode}. No live destination is requested.</p>}</main>;}createRoot(document.getElementById('root')).render(<CareerProvider><View/></CareerProvider>);`,loader:'tsx',resolveDir:root},bundle:true,outfile:join(dir,'app.js'),logLevel:'silent'});
const server=createServer(async(req,res)=>{try{const path=new URL(req.url,'http://127.0.0.1:5232').pathname;if(path==='/phone'){res.writeHead(200,{'Content-Type':'text/html; charset=utf-8'});return res.end('<!doctype html><html><meta name="viewport" content="width=device-width,initial-scale=1"><title>390px example QA</title><body style="margin:0;background:#ddd"><iframe title="Fictional 390px phone viewport" src="/" style="display:block;width:390px;height:844px;border:0;margin:auto"></iframe></body></html>');}if(['/app.js','/app.css'].includes(path)){res.writeHead(200,{'Content-Type':path.endsWith('.js')?'application/javascript':'text/css'});return res.end(await readFile(join(dir,path.slice(1))));}res.writeHead(200,{'Content-Type':'text/html; charset=utf-8'});res.end('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Fictional evidence example</title><link rel="stylesheet" href="/app.css"><div id="root"></div><script src="/app.js"></script></html>');}catch{res.writeHead(500);res.end('Local fixture failed');}});
server.listen(5232,'127.0.0.1',()=>console.log('Fictional first-use preview: http://127.0.0.1:5232'));
process.on('SIGINT',async()=>{server.close();await rm(dir,{recursive:true,force:true});process.exit(0);});
